  if (n.t === 'ref') addCell(set, n.addr)
  else if (n.t === 'range') {
    const a = addrParts(n.a)
    const b = addrParts(n.b)
    if (!a || !b) return
    const c1 = Math.min(colIndex(a.col), colIndex(b.col))
    const c2 = Math.max(colIndex(a.col), colIndex(b.col))
    const r1 = Math.min(a.row, b.row)
    const r2 = Math.max(a.row, b.row)
    for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) set.set(`${c}:${r}`, { addr: colName(c) + r, col: c, row: r })
