{"file_path":"src/util.js","content":"export function addrParts(a) {
  const m = /^([A-Z]{1,2})([0-9]{1,3})$/.exec(a)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: m[1], row }
}

export function colIndex(c) {
  return c.length === 1 ? c.charCodeAt(0) - 64 : 26 * (c.charCodeAt(0) - 64) + (c.charCodeAt(1) - 64)
}

export function colName(c) {
  return c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26))
}

export function formatValue(v) {
  switch (v.k) {
    case 'n':
      return String(Number(v.v.toPrecision(10)))
    case 'b':
      return v.v ? 'TRUE' : 'FALSE'
    case 'e':
      return v.v
    default:
      return v.v
  }
}
