{"file_path":"src/parse.js","content":"const ERR = { err: true }

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0].toUpperCase() })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  return toks
}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return ERR
  let p = 0
  const fail = () => {
    throw ERR
  }
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const CMP = ['=', '<>', '<', '<=', '>', '>=']

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && CMP.includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function isRangeAhead() {
    const a = toks[p]
    const b = toks[p + 1]
    const c = toks[p + 2]
    const d = toks[p + 3]
    return (
      a && a.k === 'word' && b && b.k === 'op' && b.v === ':' && c && c.k === 'word' && d && d.k === 'op' && (d.v === ',' || d.v === ')') &&
      !['TRUE', 'FALSE'].includes(a.v) && !['TRUE', 'FALSE'].includes(c.v)
    )
  }
  function arg() {
    if (isRangeAhead()) {
      const n = { t: 'range', a: toks[p].v, b: toks[p + 2].v }
      p += 3
      return n
    }
    return cmp()
  }
  function primary() {
    const tk = toks[p]
    if (!tk) fail()
    if (tk.k === 'num') {
      p++
      return { t: 'num', v: tk.v }
    }
    if (tk.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            args.push(arg())
            if (isOp(',')) p++
            else if (isOp(')')) {
              p++
              break
            } else fail()
          }
