      if (tk.v === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', addr: tk.v }
    }
    if (tk.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return e
    }
    return fail()
  }

